insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('4c10b942-4bd6-50e6-b6de-8c680338f9b1','HISTOPATHOLOGIC FINDINGS OF WARTS - SUMMARY','histopathologic-findings-of-warts-summary','Some differences between Myrmecia warts and Molluscum contagious Image credit This lesion is caused by Submit a form. Correct answer is HPV 1 Hamamatsu JPEG Library, version [2.0.18.50] This lesion is caused by…','https://pathologymcq.com/histopathologic-findings-of-warts-summary/','https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/05/D2F72C9E-222D-4004-9A51-82189DCD5ABA.jpeg?resize=1024%2C722&ssl=1',(select id from public.categories where slug='frcpath-part-1-histopathology'),array(select id from public.categories where slug in ('histopathology','skin-pathology')),'published','[{"id": "c6a796af-e0b6-5c14-8eae-200229817a76", "type": "paragraph", "text": "Some differences between Myrmecia warts and Molluscum contagious\nImage credit\nThis lesion is caused by\nSubmit a form.\nCorrect answer is  HPV 1\nHamamatsu JPEG Library, version [2.0.18.50]\nThis lesion is caused by\nSubmit a form.\nCorrect answer is HPV 11\nFind a tweetorial on viral inclusion bodies\nA 17-year old male presented with recurrent oral ulcers. Punch biopsy was performed.  Microscopy showed  finding in the image.  What is your diagnosis?\n#pathologymcq\n#pathtwitter\n#pathboards\n#usmle\n#plab\n#neetpg\n#pathtweetorial\n#pathtweet\n#pathresidents\n.\n#histopathology\n#infection\npic.twitter.com/pIBCix84WX\n— Pathology mcqs (@Pathology_mcqs)\nNovember 11, 2022", "align": "left", "width": 100}, {"id": "ea4ccaa5-40eb-5ddf-aedf-77d1cfdc478f", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/05/D2F72C9E-222D-4004-9A51-82189DCD5ABA.jpeg?resize=1024%2C722&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "4515e658-7d81-5d75-809f-e94f183de307", "type": "image", "src": "https://i0.wp.com/p