insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('50d7ab53-1027-5564-b076-aa2f94323cf6','PEDIATRIC RENAL  TUMORS QUIZ','pediatric-renal-tumors-quiz','SOLVE QUIZ NOW!! Preparing for NEET-SS Oncopathology? Get Course Here Preparing for FRCPath Part 1 Histopathology (Autumn 2023) Register for the upcoming course','https://pathologymcq.com/pediatric-renal-tumors-quiz/',NULL,(select id from public.categories where slug='histopathology'),array(select id from public.categories where slug in ('nephropathology')),'published','[{"id": "9d89e945-09f4-5866-adfe-e008c4ad5f19", "type": "paragraph", "text": "SOLVE QUIZ NOW!!\nPreparing for NEET-SS Oncopathology?\nGet Course Here\nPreparing for FRCPath Part 1 Histopathology (Autumn 2023)\nRegister for the upcoming course", "align": "left", "width": 100}]'::jsonb,('2022-11-25T22:28:42'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('c4dfaa86-3eff-581f-8526-6435bb85a7c5','NUCLEAR INCLUSIONS AND PSEUDO-INCLUSIONS','nuclear-inclusions-and-pseudo-inclusions','TRUE NUCLEAR INCLUSIONS CAUSES: Viral particles Accumulation of extracellular substances (surfactant, glycogen, polyglutamates etc) and Neuronal inclusions. 1. VIRAL PARTICLES 2. ACCUMULATION OF EXTRACELLULAR…','https://pathologymcq.com/nuclear-inclusions-and-pseudo-inclusions/','https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/11/5nkbakd8maz91.jpg?resize=720%2C768&ssl=1',(select id from public.categories where slug='histopathology'),array(select id from public.categories where slug in ('general-pathology')),'published','[{"id": "2d96f3cf-92db-5bdd-85cf-5b20ba66f070", "type": "paragraph", "text": "TRUE NUCLEAR INCLUSIONS\nCAUSES:\nViral particles\nAccumulation of extracellular substances (surfactant, glycogen, polyglutamates etc) and Neuronal inclusions.\n1. VIRAL PARTICLES\n2.  ACCUMULATION OF EXTRACELLULAR SUBSTANCES\nPSEUDO-NUCLEAR INCLUSIONS\nCaused by cytoplasmic invagination\nSOME DIFFERENCES BETWEEN NUCLEAR INCLUSIONS, PSEUDO-INCLUSIONS AND PSEUDO-PSEUDO INCLUSIONS\nIllustration credit:\nhttps://twitter.com/VijayPatho\nREVIEW QUESTION\nWhich of the following virus does not produce intra-nuclear inclusions? (Question from AIIMS SR exam Jan 2023)\nA. Varicella zoster virus\nB. Variola\nC. Herpes simplex\nD. Polio\nCLICK FOR ANSWER\nAnswer is B. Variola\nEXPLANATION\nCauses of intra-nuclear viral inclusions\nNuclear eosinophilic (acidophilic)-\nCowdry bodies type A in\nHerpes simplex virus\nand\nVaricella zoster virus\nTorres bodies in\nyellow fever\nCowdry bodies type B in\npolio\nand\nadenovirus\nNuclear basophilic-\nCowdry bodies type B in\nadenovirus\n“Owl’s eye appearance” in\ncytomegalovirus\nBoth nuclear and cytoplasmic-\nWarthin–Finkeldey bodies in\nmeasles\nand\nHIV/AIDS\nMORE EXPLANATION\nVariola has cytoplasmic inclusions known as Guarnieri bodies\nFIND TWEETORIALS ON THE TOPIC\nA 17-year old male presented with recurrent oral ulcers. Punch biopsy was performed.  Microscopy showed  finding in the image.  What is your diagnosis?\n#pathologymcq\n#pathtwitter\n#pathboards\n#usmle\n#plab\n#neetpg\n#pathtweetorial\n#pathtweet\n#pathresidents\n.\n#histopathology\n#infection\npic.twitter.com/pIBCix84WX\n— Pathology mcqs (@Pathology_mcqs)\nNovember 11, 2022\nA 65 year old male presented with low urine output and bone pain. On further investigation serum creatinine was high and the patient had low hemoglobin. Bone marrow biopsy showed finding in the image. What is your diagnosis?\n#pathtwitter\n#pathtweetorial\n#pathresidents\n#pathboards\npic.twitter.com/R8NobF3nnM\n— Pathology mcqs (@Pathology_mcqs)\nNovember 15, 2022", "align": "left", "width": 100}, {"id": "2d16fab5-4b55-53c8-a3ea-c0bcc32fb5f2", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/11/5nkbakd8maz91.jpg?resize=720%2C768&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "58c80224-8b2d-5c8d-97c9-cadd9194188e", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/11/x416zsi8maz91.jpg?resize=719%2C922&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "82d320ea-fc1a-5224-a23e-0ecf4057850b", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/11/tqhco8r8maz91.jpg?resize=720%2C871&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "2c53d974-c5c0-5db8-bacd-bf575e3452a6", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/11/egdjz019maz91.jpg?resize=719%2C744&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "a3e1ca3e-0cdc-5c15-b0ad-afaace15cac6", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/11/3q6york9maz91.jpg?resize=720%2C577&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "d6df96