insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('6076af8a-0fba-569c-a8a0-d12619ceecc5','INI-SS DM HEMATOPATHOLOGY AND HISTOPATHOLOGY MOCK TESTS +MINI MOCK TESTS','ini-ss-dm-hematopathology-and-histopathology-mock-tests','INI-SS HISTOPATHOLOGY AND HEMATOPATHOLOGY PRACTISE TESTS Exam pattern mock tests and mini mock tests for DM Hematopathology and DM Histopathology. Duration: 90 minutes Number of Questions : 80 Questions Total Marks :…','https://pathologymcq.com/ini-ss-dm-hematopathology-and-histopathology-mock-tests/',NULL,(select id from public.categories where slug='histopathology'),array(select id from public.categories where slug in ('hematopathology','hematopathology-mcqs-ini-ssdm')),'published','[{"id": "51254dbe-f418-5f92-927a-baeaac7721f6", "type": "paragraph", "text": "INI-SS HISTOPATHOLOGY AND HEMATOPATHOLOGY PRACTISE TESTS\nExam pattern mock tests and mini mock tests for DM Hematopathology and  DM Histopathology.\nDuration: 90 minutes\nNumber of Questions : 80 Questions\nTotal Marks : 80 Marks\nLanguage : English\nType of Questions : Objective type of questions of Single Correct Choice.\nCorrect Answer : One Mark (+1)\nIncorrect Answer : Minus one-third (-) 1/3\nUnanswered  : 0\n50% from general pathology and 50 % from speciality.\nEACH MOCK TEST FOR Rs :599\nhttps://pathologymcq.com/product/dm-histopathology-ini-ss-mock-test/\nhttps://pathologymcq.com/product/dm-hematopathology-ini-ss-mock-test/\nACCESS HISTOPATHOLOGY MOCK TEST HERE\nACCESS HEMATOPATHOLOGY MOCK TEST HERE\nMini mock test (40 questions- 20 general pathology and 20 speciality).\nhttps://pathologymcq.com/product/dm-hematopathology-ini-ss-mini-mock-test/\nhttps://pathologymcq.com/product/dm-histopathology-ini-ss-mini-mock-test/\nACCESS HEMATOPATHOLOGY-MINI TEST\nACCESS HISTOPATHOLOGY MINI TEST\nSend us a message\nHave questions or need a hand? We’re here to help. Reach our friendly support team via