insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('13ab876b-036e-56d5-8025-e1de05a32152','Some Histopathology Short quizzes','some-histopathology-short-quizzes','INI-SS HISTOPATHOLOGY MOCK TESTS + MINI MOCK TEST- ALSO USEFUL FOR NEET-SS ONCOPATHOLOGY / FELLOWSHIPS AND SENIOR RESIDENCY EXAMS. GET NOW Some Histopathology SHORT QUIZZES are listed below.. Key focus:…','https://pathologymcq.com/some-histopathology-short-quizzes/',NULL,(select id from public.categories where slug='histopathology'),array(select id from public.categories where slug in ('oncopathology','general-pathology','immunohistochemistry','robbins-questions')),'published','[{"id": "90cf293b-f9f1-5ef2-a42b-cceeaea19986", "type": "paragraph", "text": "INI-SS HISTOPATHOLOGY MOCK TESTS + MINI MOCK TEST- ALSO USEFUL FOR NEET-SS ONCOPATHOLOGY / FELLOWSHIPS AND SENIOR RESIDENCY EXAMS.\nGET NOW\nSome Histopathology SHORT QUIZZES are listed below..\nKey focus: Immunohistochemistry\nBreast pathology – IHC MCQs\nIHC MCQs- Based on CK7 /CK20\nImmunohistochemistry MCQs\nKey focus: Skin pathology\nBullous disorders – MCQs\nSquamous cell carcinoma- MCQs\nBasal cell carcinoma- MCQs\nMelanocytic tumors- MCQs\nSkin appendage tumors – MCQs\nKey focus: Latest WHO Updates.\nLUNG TUMORS MCQs based on Latest WHO updates\nFGT pathology WHO 2020- Quiz\nChat on WhatsApp", "align": "left", "width": 100}]'::jsonb,('2022-10-22T17:32:15'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('55a662d7-e8d7-5b3a-b28e-d9ea590a01cc','CAN YOU GUESS THE TYPE OF LEIOMYOMA BASED ON THE MORPHOLOGY?','can-you-guess-the-type-of-leiomyoma-based-on-the-morphology','Here are a few images, all you got to do is to guess the type of genetic mutation in the leiomyoma just based on the morphology. Focus on the nucleus… Spindle to oval shaped nucleus with bright eosinophilic nucleoli…','https://pathologymcq.com/can-you-guess-the-type-of-leiomyoma-based-on-the-morphology/','https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/10/case352image6.jpg?resize=1000%2C750&ssl=1',(select id from public.categories where slug='histopathology'),array(select id from public.categories where slug in ('female-genital-pathology','soft-tissue-pathology')),'published','[{"id": "53f90970-d1d0-5218-a902-5a3630568a14", "type": "paragraph", "text": "Here are a few images, all you got to do is to guess the type of genetic mutation  in the  leiomyoma just based on the morphology.\nFocus on the nucleus…\nSpindle to oval shaped nucleus with bright eosinophilic nucleoli surrounded by a halo.\nSee those rhabdoid eosinophilic inclusions?\nWhat do you think the type of leiomyoma is?\nA. Leiomyoma with bizzare nuclei\nB. Fumarate hydratase deficient leiomyoma\nC. Cellular leiomyoma\nD. Mitotically active leiomyoma\nANSWER\nThe correct answer is B- Fumarate hydratase deficient leiomyoma.\nOption A: Leiomyoma with bizzare nuclei does not have an eosinophilic nucleoli.\nOption C: Cellular leiomyoma is more cellular than the adjacent myometrium.\nOption D: Mitotically active leiomyoma has a mitosis of > 4-10/ HPF\nDIFFERENCE BETWEEN FUMARATE HYDRATASE DEFICIENT LEIOMYOMA AND LEIOMYOMA WITH BIZZARE NUCLEI\nDifference between leiomyoma with bizzare nuclei and fumarate hydratase deficient leiomyoma.\nFIND A RELEVANT TWEETORIAL\nCan you guess the genetic mutation in this leiomyoma based on the histopathology?\n#PathTwitter\n#pathboards\n#pathresidents\n#pathologymcq\n#pathology\n#MedTwitter\n#histopathology\n#histology\n#fgtpath\n#dmhistopathology\n#frcpath1\n#rcpath\n#frcpath\n#pathtweet\n#pathtweetorial\n#tweetorial\npic.twitter.com/vX1N0n6ZCY\n— Pathology mcqs (@Pathology_mcqs)\nOctober 9, 2022\nTweetorial", "align": "left", "width": 100}, {"id": "dd960dba-c8a0-5ec3-aa8e-727291959c0b", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/10/case352image6.jpg?resize=1000%2C750&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "330d44a9-9cba-549c-ae06-7852e3be4140", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/10/case352image4.jpg?resize=476%2C578&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "57e99c4b-fa6d-552b-960e-ab9e9a9e6f74", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/10/images-2022-10-17T130325.128.jpeg?resize=401%2C301&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "71f37230-6fda-5af4-a6a5-94fdb85401a6", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/10/IMG_20221017_130833_357.jpg?resize=397%2C706&ssl=1", "alt": "", "align": "left", "width": 100}]'::jsonb,('2022-10-17T17:54:22'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('7308d16f-7db1-5065-baec-51bb887c8a20','Difference between clear cell RCC (renal cell carcinoma) and clear cell papillary RCC','difference-between-clear-cell-rcc-renal-cell-carcinoma-and-clear-cell-papillary-rcc','Clear cell renal cell carcinoma (RCC) can be differentiated from clear cell papillary RCC based on morphology, immunohistochemistry and molecular genetics. Prognosis also varies between the two. Key differences…','https://pathologymcq.com/difference-between-clear-cell-rcc-renal-cell-carcinoma-and-clear-cell-papillary-rcc/','https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/10/Copy-of-Notebook-Lesson-_-by-Slidesgo-1.jpg?resize=683%2C1024&ssl=1',(select id from public.categories where slug='histopathology'),array(select id from public.categories where slug in ('molecular-pathology','oncopathology','immunohistochemistry','staining','nephropathology')),'published','[{"id": "6dc7fd3b-1af1-5d41-9d67-8e04bb42904f", "type": "paragraph", "text": "Clear cell renal cell carcinoma (RCC) can be differentiated from clear cell papillary RCC based on morphology, immunohistochemistry and molecular genetics. Prognosis also varies between the two.\nKey differences between the two conditions are elaborated below.\nPathology boards practice questions- RENAL PATHOLOGY", "align": "left", "width": 100}, {"id": "f557d5f8-95b5-54fc-8bb0-bd8c2275be2e", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/10/Copy-of-Notebook-Lesson-_-by-Slidesgo-1.jpg?resize=683%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}]'::jsonb,('2022-10-03T11:59:15'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('b428d0b1-e0eb-59b5-96a7-9a93977e819f','PARIS SYSTEM FOR REPORTING URINARY CYTOLOGY MCQs','paris-system-for-reporting-urinary-cytology-mcqs','USEFUL FOR NEET-SS/ DM- Oncopathology/ DM Histopathology Oncopathology Fellowships , Cytopathology fellowships. FRCPath- Histopathology American Board of anatomic and clinical pathology Various other boards. QUIZ…','https://pathologymcq.com/paris-system-for-reporting-urinary-cytology-mcqs/',NULL,(select id from public.categories where slug='histopathology'),array(select id from public.categories where slug in ('weekly-quizzes')),'published','[{"id": "9e538ed9-4222-5315-9a4f-05d4f1104ef5", "type": "paragraph", "text": "USEFUL FOR\nNEET-SS/ DM- Oncopathology/ DM Histopathology\nOncopathology Fellowships , Cytopathology fellowships.\nFRCPath- Histopathology\nAmerican Board of anatomic and clinical pathology\nVarious other boards.\nQUIZ WILL BE LIVE ON 27/03/22(Sunday) –   9 AM IST.\nCLICK HERE TO ACCESS QUIZ\nClick HERE for  pathology quizzes", "align": "left", "width": 100}]'::jsonb,('2022-03-22T11:06:38'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('7549aba3-aa01-5a4a-bc5f-8c2aee78f430','CNS Pathology case based MCQs-Ependymoma','cns-pathology-case-based-mcqs-2','CASE : The spinal MRI of a 22-year old male with neurofibromatosis type-2 showed a hyperintense lesion. The lesion was resected and histopathologic section is shown in image. Question 1: What is the diagnosis? A.…','https://pathologymcq.com/cns-pathology-case-based-mcqs-2/','https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/02/images-27.jpeg?resize=400%2C335&ssl=1',(select id from public.categories where slug='histopathology'),array(select id from public.categories where slug in ('neuropathology')),'published','[{"id": "b82524cc-a31a-58b2-ab7b-30f7a2e71721", "type": "paragraph", "text": "CASE :\nThe spinal MRI of a 22-year old male with neurofibromatosis type-2 showed a hyperintense lesion. The lesion was resected and histopathologic section is shown in image.\nQuestion 1:\nWhat is the diagnosis?\nA. Medulloblastoma\nB. Ependymoma\nC. Retinoblastoma\nD. Central neurocytoma\nQuestion 2:\nWhich of the following statements is true regarding this tumor?\nA. They are predominantly supratentorial\nB. Posterior fossa tumors in adults have a good prognosis\nC. Spinal tumors have a bad prognosis\nD. IDH 1 and 2 mutations are present in 100% cases.\nQuestion 3:\nIdentify the variant of the tumor shown in the image below.\nA. Tancytic\nB. Myxopapillary\nC. Subependymoma\nD. Anaplastic\nQuestion 4:\nWhich of the following statements is true regarding tancytic ependymoma?\nA. GFAP negative\nB. Abundant rosettes\nC. Can be confused with pilocytic astrocytoma\nD. WHO Grade 1\nQuestion 5:\nIdentify the\nFALSE\nstatement regarding the variant of ependymoma shown below\nImage credit-\nhttp://www.twitter.com/DrAldehyde\nA. WHO Grade 1\nB. Arises from filum terminale\nC. Aggressive clinical course\nD. Mucin stains positive\nQuestion 6: TRUE\nstatement regarding recent molecular classification (WHO CNS 2021 5th edition ) of ependymoma is\nA. Spinal ependymomas with MYCN have a good prognosis\nB. ZFTA Fusion- favorable prognosis\nC. YAP Fusion- poor prognosis\nD. Spinal ependymomas with NF 2  mutation- favorable prognosis\nANSWER- Question 1\nCorrect answer is B- Ependymoma\nEpendymomas are characterized by perivascular rosettes and ependymal rosettes which have an empty central lumen\nTypes of rosettes\nANSWER- Question 2\nCORRECT ANSWER IS B\n🐱 Majority of of Ependymomas are infratentorial.\n🐱Posterior fossa tumors in children have a poor prognosis (PF-A)- associated with loss of H3K27me, whereas Posterior fossa tumors in adults have a god prognosis (PF-B)- H3K27me is retained.\n🐱 Spinal ependymomas have a good prognosis, whereas a small number of ependymomas associated with MYCN have a poor outcome.\n🐱IDH 1 and 2 are associated with astroctyomas and oligodendroglomas but nor ependymomas.\nANSWER-Question 3\nCORRECT ANSWER IS A\nDiagnosis is TANCYTIC EPENDYMOMA, 🐱 Tancytes are cells with fibrillary processes which line ventricles along with ependymal cells.\nTypes of tancytes\nANSWER – Question 4\nCorrect They are GFAP positive 🐱Confused with pilocytic astrocytoma because of the prominent fibrillary projections 🐱It is a GRADE II Ependymoma 🐱 Ependymal rosettes and pseudorosettes are scanty in tanytic ependymoma, which makes diagnosis challenging.\nANSWER- Question 5\nCorrect answer is C\n💀Diagnosis is myxopapillary ependymoma\n💀It is a Grade II Tumor according to latest WHO\n💀It is common in adults and arises from the filum terminale\n💀It is clinically indolent ( nor aggressive)\n💀Stains for Mucin is positive.\nMucin stains positive in myxopapillary ependymoma\nANSWER – Question 6\nCorrect answer is D\nSpinal ependymomas with NF2 mutation has a good prognosis\nSummary of latest molecular updates in ependymoma\nhttps://www.pinterest.com/pin/1140114461888911764/sent/?invite_code=8c0c292164cb49309c55337a1d93b1a7&sender=1140114599324959776&sfo=1\nInstagram\nFacebook\nTelegram\nReddit\nWhatsApp\nX\nLinkedIn\nPinterest", "align": "left", "width": 100}, {"id": "3304c115-221c-5dd9-904c-714f8a0962c0", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/02/images-27.jpeg?resize=400%2C335&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "7e3909dc-9946-5fa0-a483-bc711b90b0e8", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/02/images-30.jpeg?resize=639%2C480&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "a9abe432-1597-5446-9b3f-d52e6695a933", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/02/20220216_212822.jpg?resize=1024%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "380eb471-f632-54c7-afbe-8560c39a9ee1", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/02/images-28.jpeg?resize=543%2C529&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "2b054cde-cd4b-534e-8b70-09ab1f776dfc", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/02/images-29.jpeg?resize=383%2C400&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "e8c126ba-1fbd-5842-8293-6b122b01c05a", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/02/images-49.jpeg?resize=643%2C477&ssl=1", "alt": "", "align": "left", "width": 100}]'::jsonb,('2022-02-23T19:55:16'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
