insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('89ada7f9-1b68-508a-a142-28db8f41ef26','THYROID PATHOLOGY QUIZ','thyroid-pathology-quiz','USEFUL FOR NEET-SS/ DM- Oncopathology/ DM Histopathology Oncopathology Fellowships FRCPath- Histopathology and American Board of anatomic and clinical pathology Various other boards. CLICK HERE FOR THYROID PATHOLOGY…','https://pathologymcq.com/thyroid-pathology-quiz/',NULL,(select id from public.categories where slug='histopathology'),array(select id from public.categories where slug in ('endocrine-pathology','weekly-quizzes')),'published','[{"id": "c79a1218-2a89-5020-a3aa-14aa96dc1fcb", "type": "paragraph", "text": "USEFUL FOR\nNEET-SS/ DM- Oncopathology/ DM Histopathology\nOncopathology Fellowships\nFRCPath- Histopathology and\nAmerican Board of anatomic and clinical pathology\nVarious other boards.\nCLICK HERE FOR THYROID PATHOLOGY QUIZ\nClick HERE for  pathology quizzes", "align": "left", "width": 100}]'::jsonb,('2021-10-26T10:43:15'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('0070c7b3-582a-59d0-8c0d-7d8a2be9fe4b','ENDOCRINE PATHOLOGY QUIZ','endocrine-pathology-quiz','ENDOCRINE PATHOLOGY QUIZ. USEFUL FOR NEET-SS/ DM- Oncopathology/ DM Histopathology Oncopathology Fellowships FRCPath- Histopathology and American Board of anatomic and clinical pathology Various other boards. CLICK…','https://pathologymcq.com/endocrine-pathology-quiz/',NULL,(select id from public.categories where slug='histopathology'),array(select id from public.categories where slug in ('endocrine-pathology','weekly-quizzes')),'published','[{"id": "32f04b15-ac68-5904-a39f-05a2911c018c", "type": "paragraph", "text": "ENDOCRINE PATHOLOGY QUIZ.\nUSEFUL FOR\nNEET-SS/ DM- Oncopathology/ DM Histopathology\nOncopathology Fellowships\nFRCPath- Histopathology and\nAmerican Board of anatomic and clinical pathology\nVarious other boards.\nCLICK HERE FOR ENDOCRINE PATHOLOGY QUIZ\nClick HERE for  pathology quizzes", "align": "left", "width": 100}]'::jsonb,('2021-08-02T03:11:08'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('b5ccabd4-9eaa-5079-9d21-d7c128ca1453','Kimura Disease vs Epithelioid Hemangioma: Key Differences','differences-between-kimura-disease-and-angiolymphoid-hyperplasia-with-eosinophilia','Kimura disease and Epithelioid hemangioma (Previously , Angiolymphoid hyperplasia with eosinophilia (ALHE) ) are often confused and need to be differentiated. Here are a few differences. 1.AGE Kimura’s disease is a…','https://pathologymcq.com/differences-between-kimura-disease-and-angiolymphoid-hyperplasia-with-eosinophilia/','https://i0.wp.com/pathologymcq.com/wp-content/uploads/2024/06/445517620_17999849891555760_7942976120474116722_n.jpg?resize=869%2C1024&ssl=1',(select id from public.categories where slug='histopathology'),array(select id from public.categories where slug in ('hematopathology','hematology')),'published','[{"id": "49ebbcc2-9820-533c-a072-22f739f0489c", "type": "paragraph", "text": "Kimura disease and  Epithelioid hemangioma (Previously , Angiolymphoid hyperplasia with eosinophilia (ALHE) ) are often confused and need to be differentiated. Here are a few differences.\n1.AGE\nKimura’s disease is a chronic inflammatory condition of unknown cause that affects young to middle-aged patients, most often males of Asian descent. Whereas, ALHE is more common in females.\n2.LOCATION\nKimura disease patients usually have a mass in the head and neck region with involvement of subcutaneous tissue, soft tissue, salivary glands, and single or multiple regional lymph nodes. Epithelioid Hemangioma also commonly involves the head and neck region, particularly behind the ears.\n3.HISTOLOGY\nKey histologic features of kimura disease includes florid follicular hyperplasia  that may contain a proteinaceous precipitate (IgE in a follicular dendritic network pattern) and vascularization of the germinal centers. The interfollicular areas show prominent high endothelial venules with a mixture of lymphocytes, plasma cells, eosinophils, and mast cells. Follicle lysis is often present, and eosinophilic abscesses are characteristic within germinal centers as well as in the paracortex.\nEpithelioid Hemangioma on the other hand, is a vascular neoplasm characterized by the proliferation of blood vessels lined by plump endothelial cells with abundant eosinophilic cytoplasm, imparting a hobnail appearance. This lesion is part of the spectrum of what have been called histiocytoid or epithelioid hemangiomas, and is a low-grade vascular tumor. There is a dense, mixed inflammatory cell infiltrate consisting of lymphocytes, plasma cells, and eosinophils.\n4. IMMUNOHISTOCHEMISTRY\nReticular pattern of IgE is seen in KIMURA disease. However, immunohistochemistry in Epithelioid Hemangioma is positive for CD 31, CD 34 and Factor VIII in the vascular component.\nFOSB- IHC is usually positive in Epithelioid hemangioma\n5.PERIPHERAL BLOOD EOSINOPHILIA\nPeripheral blood examination shows eosinophilia and increased serum IgE levels in kimura disease but not so much in Epithelioid Hemangioma.\nFIND A QUICK SUMMARY BELOW\nhttps://www.pinterest.com/pin/1140114461886846593/sent/?invite_code=813193369a4b4d22b76b0347630622cd&sender=1140114599324959776&sfo=1\nView this post on Instagram\nA post shared by Pathology MCQs (@pathology_mcqs)\nREVIEW QUESTION\n1. A 20- year- old Asian male has eosinophilia and high levels of IgE with cervical lymphadenopathy. Excisional biopsy of the lymph node demonstrates follicular hyperplasia, intense eosinophilia and eosinophilic microabscesses. h e most likely diagnosis is:\nA. Kimura disease\nB. Kikuchi- Fujimoto disease\nC. Eosinophilic leukemia\nD. Hypereosinophilic syndrome\nCLICK TO REVEAL ANSWER\nAnswer is A- Kimura disease like Kikuchi disease is seen more ot en in the Asian population. h e etiology is not known. h is is a chronic inl ammatory disorder of the subcutaneous tissue and af ects regional lymph nodes. h e cervical area is the most common site to be involved. Histology of the af ected lymph nodes demonstrates follicular hyperplasia, eosinophilia with eosinophilic microabscesses and ini ltration of the germinal centers. Increase in vessels may also be seen. Warthin Finkeldey giant cells may also be present.\n2. All are true about kimura disease except\nA. Affects asians\nB. Affects females\nC. Peripheral eosinophilia is present\nD. Elevated levels of IgE are seen\nCLICK HERE TO REVEAL ANSWER\nAnswer is B- Kimura disease is more common in males.\nCheck out our hematopathology course and Hard copy notes for more updates and useful topics\nHEMATOPATHOLOGY COURSE\nConcise Hematopathology Notes- Hard Copies", "align": "left", "width": 100}, {"id": "8e434dfe-a428-537e-bfaf-e6ecdc8801fc", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2024/06/445517620_17999849891555760_7942976120474116722_n.jpg?resize=869%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "881c8427-02b1-5058-94b9-8c3fd72e989f", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2024/06/444990903_17999849906555760_8955213381655170346_n.jpg?resize=869%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}]'::jsonb,('2021-07-29T14:31:07'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
