insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('f5b4765d-bf58-54c7-a9ee-8c3043231edf','Characteristics of Epithelial-Mesenchymal transition','characteristics-of-epithelial-mesenchymal-transition','Epithelial Mesenchymal Transition EMT- Epithelial mesenchymal transition It is integral to breast and prostrate cancers. EMT is controlled by SNAIL and TWIST proteins. Down regulation of epithelial markers and…','https://pathologymcq.com/characteristics-of-epithelial-mesenchymal-transition/','https://i0.wp.com/pathologymcq.com/wp-content/uploads/2021/12/IMG_20211207_212729.jpg?resize=1000%2C475&ssl=1',(select id from public.categories where slug='general-pathology'),'{}'::uuid[],'published','[{"id": "f54f8d25-3692-569e-97be-1228dc195049", "type": "paragraph", "text": "Epithelial Mesenchymal Transition\nEMT- Epithelial mesenchymal transition\nIt is integral to breast and prostrate cancers.\nEMT is controlled by SNAIL and TWIST proteins.\nDown regulation of epithelial markers and upregulation of mesenchymal markers.\nE cadherin expression is slilenced\nStrong migratory potential", "align": "left", "width": 100}, {"id": "36a2d4a8-f2d3-54e6-85e8-ec54250e208e", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2021/12/IMG_20211207_212729.jpg?resize=1000%2C475&ssl=1", "alt": "", "align": "left", "width": 100}]'::jsonb,('2021-12-07T21:30:31'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('bf4d5823-64ab-5f5c-a8ce-820455bfb78d','ROBBINS PATHOLOGY 10TH Edition - Chapter 2 MCQs PDF','robbins-pathology-mcqs-pdf-download','COMPILATION OF ROBBINS 10TH EDITION CHAPTER 2 MCQS- PDF DOWNLOAD Find Robbins pathology chapter 2 mcqs with answers pdf for download. Robbins chapter 2 mcqs Robbins-chapter-2-mcqs Download CLICK HERE FOR ROBBINS…','https://pathologymcq.com/robbins-pathology-mcqs-pdf-download/','https://i0.wp.com/pathologymcq.com/wp-content/uploads/2021/03/images2817293588019887290646802..jpg?resize=489%2C627&ssl=1',(select id from public.categories where slug='general-pathology'),array(select id from public.categories where slug in ('robbins-questions')),'published','[{"id": "99215b66-1b61-56ab-9803-985a5209c0aa", "type": "paragraph", "text": "COMPILATION OF ROBBINS 10TH EDITION CHAPTER 2 MCQS- PDF DOWNLOAD\nFind Robbins pathology chapter 2 mcqs with answers pdf for  download.\nRobbins chapter 2 mcqs\nRobbins-chapter-2-mcqs\nDownload\nCLICK HERE FOR ROBBINS PATHOLOGY 10TH EDITION CHAPTERWISE MCQS\nYou may join telegram channel for more mcqs-\nPathology mcqs", "align": "left", "width": 100}, {"id": "8421f979-d924-536a-8737-3ac3011243f7", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2021/03/images2817293588019887290646802..jpg?resize=489%2C627&ssl=1", "alt": "", "align": "left", "width": 100}]'::jsonb,('2021-06-22T13:09:25'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('c260a4e5-ff15-5a83-abaf-7a6621b2dca7','Robbins pathologic basis of disease 10th edition updates','robbins-pathology-10th-edition-updates','Robbins pathologic basis of disease 10th edition has a handful of changes and updates when compared to it’s predecessor. Here is a brief note on the chapterwise general pathology updates which are high yield for…','https://pathologymcq.com/robbins-pathology-10th-edition-updates/','https://i0.wp.com/pathologymcq.com/wp-content/uploads/2021/06/IMG_20210611_192702.jpg?resize=641%2C820&ssl=1',(select id from public.categories where slug='general-pathology'),'{}'::uuid[],'published','[{"id": "697ad6d1-8b94-5883-b7da-fc393c47210a", "type": "paragraph", "text": "Robbins pathologic basis of disease 10th edition has a handful of changes and updates when compared to it’s predecessor.\nHere is a brief note on the chapterwise\ngeneral pathology\nupdates\nwhich are high yield for entrance exams.\nROBBINS 10TH EDITION CHAPTERWISE UPDATES\nCHAPTER 1-\nCELL\nSatellite DNA\n– A major component of centromeres is so-called satellite DNA, consisting of large arrays—up to megabases in length—of repeating sequences (from 5 bp up to 5 kb). Although classically associated with spindle apparatus attachment, satellite DNA is also important in maintaining the dense, tightly packed organization of heterochromatin.\nGene Editing and CRISPR-\nAn exciting new development that allows high-fidelity genome editing may usher in the next era of the molecular revolution. This advance comes from a wholly unexpected source: the discovery of clustered regularly interspaced short palindromic repeats (CRISPRs) and CRISPR-associated genes (Cas), such as the Cas9 nuclease.\nCrispr/ cas9 system update Robbins 10 th edition\nCHAPTER 2- ADAPTATIONS AND INJURY\nFerroptosis-\nOnly discovered in 2012, ferroptosis is a distinct form of cell death that is triggered when excessive intracellular levels of iron or reactive oxygen species overwhelm the glutathione-dependent antioxidant defenses.\nCHAPTER 3-INFLAMMATION AND REPAIR\nNeutrophil extracellular traps (NETs)\n–\nNETs were mentioned in the previous edition it is further elaborated in the latest edition. Neutrophil extracellular traps (NETs) are extracellular fibrillar networks that concentrate antimicrobial substances at sites of infection and trap microbes, helping to prevent their spread.\nCHAPTER 6- IMMUNITY\nRejection of tissue transplants:\nElaborated compared to the previous edition\n.\nCHAPTER 7- NEOPLASIA\nA few newly added proto-oncogenes:\nFMS-like tyrosine kinase 3 (FLT3) Point mutation or small duplications in Leukemia.\nGTP-binding (G) proteins- GNAQ Point mutation in Uveal melanoma.\nGTP-binding (G) proteins- GNAS Point mutation in Pituitary adenoma.\nA few newly added tumor suppessor genes:\nSDHB, SDHD (Succinate dehydrogenase complex subunits B and D TCA cycle, oxidative phosphorylation) seen in Familial paraganglioma, familial pheochromocytoma.\nElaboration of oncogenic activities of E6 an E7 proteins of human papilloma virus (HPV)\nHuman papilloma virus update Robbins pathology 10th edition\nIn the older edition it was mentioned that the E6 protein of HPV inactivates p53. In the 10th edition it is mentioned that in addition to inactivation of p53, E6 protein also increases telomerase expression (TERT).\nCHAPTER 8- INFECTIOUS DISEASES\nUpdates on the SARSCoV2 virus\nClick here for general pathology quiz\nClick here for general pathology blogs\nCelebrate International Pathology Day 2025 — 20% Off All Courses!\nby\nPathology MCQs\n5 Nov 2025\nUnderstanding Chordoma: Diagnosis and Pathology\nby\nPathology MCQs\n26 Oct 2025\nInvasive Fungal Infections: Histopathology, Causes, Treatment & MCQs\nby\nPathology MCQs\n19 Oct 2025", "align": "left", "width": 100}, {"id": "d7a20a1f-0d2b-59b0-86f3-3e48a2ed32cc", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2021/06/IMG_20210611_192702.jpg?resize=641%2C820&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "8aef3e2d-e436-5c3a-b97a-9f6c5afec71d", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2021/06/IMG_20210611_191603.jpg?resize=720%2C541&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "53fbf8d9-64b6-53ae-ac6a-76282b91431a", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2025/11/Cream-Plain-Image-Pop-Up-Instagram-Post-42.jpg?fit=1024%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "972088a5-22d7-5e6a-8cb3-c8808f9f65b7", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2025/10/Cream-Plain-Image-Pop-Up-Instagram-Post-41.jpg?fit=1024%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "47884196-5aa3-50bf-8909-6bf0f99fb965", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2025/10/Cream-Plain-Image-Pop-Up-Instagram-Post-40.jpg?fit=1024%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}]'::jsonb,('2021-06-11T19:41:04'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('3ae4ea35-79d9-522f-a469-e47eeefe6f3e','Pheochromocytoma and Paraganglioma Syndromes','pheochromocytoma-and-paraganglioma-syndromes','Pheochromocytomas and paragangliomas are rare neuroendocrine tumors that originate from chromaffin cells in the adrenal medulla or extra-adrenal sympathetic and parasympathetic tissues, respectively. They can be part…','https://pathologymcq.com/pheochromocytoma-and-paraganglioma-syndromes/','https://i0.wp.com/pathologymcq.com/wp-content/uploads/2024/09/IMG_0222.jpeg?resize=1024%2C660&ssl=1',(select id from public.categories where slug='endocrine-pathology'),array(select id from public.categories where slug in ('frcpath-part-1-histopathology')),'published','[{"id": "e5e49835-e7bd-5ed4-848d-b4f49b36a8f9", "type": "paragraph", "text": "Pheochromocytomas and paragangliomas are rare neuroendocrine tumors that originate from chromaffin cells in the adrenal medulla or extra-adrenal sympathetic and parasympathetic tissues, respectively. They can be part of inherited syndromes characterized by specific genetic mutations. Frequently asked topic in FRCPath -Part 1 Histopathology exam.\nSyndromes Associated with Pheochromocytomas and Paragangliomas\n:\nSyndrome\nGene Mutation (Function)\nClinical Phenotype\nPheochromocytoma Characteristics\nLifetime Pheochromocytoma Risk\nMEN 2A\nRET (proto-oncogene)\nMedullary thyroid cancer, primary hyperparathyroidism\nBenign, bilateral or multicentric, intra-adrenal\n50%\nMEN 2B\nRET (proto-oncogene)\nMedullary thyroid cancer, marfanoid habitus, mucosal neuromas\nBenign, bilateral or multicentric, intra-adrenal\n50%\nNeurofibromatosis Type 1\nNF1 (negative regulator of Ras oncogene pathway)\nNeurofibromas, café-au-lait spots, optic gliomas\n15% malignant; intra-adrenal\n1-5%\nVon Hippel-Lindau (VHL)\nVHL (tumor suppressor)\nRetinal angiomas, CNS hemangioblastomas, renal cancer, pancreatic cysts\nBenign, bilateral, younger age at diagnosis\n10-20%\nFamilial Paraganglioma Syndrome\nSDHA, SDHB, SDHC, SDHD (mitochondrial enzymes)\nGIST; SDHB may be associated with renal cell cancer\nSDHB: 40-80% malignant; solitary\n20-30%\nHereditary Pheochromocytoma (MAX)\nMAX (transcription regulator)\nPossibly other tumors\nBilateral or multicentric; intra-adrenal; thoraco-abdominal PG\nUnknown\nHereditary Pheochromocytoma (TMEM127)\nTMEM127 (tumor suppressor)\nPossibly other tumors\nBenign; intra-adrenal\nUnknown\nHereditary Pheochromocytoma (HIF-2α)\nHIF-2α (transcription regulator)\nPolycythemia, thoraco-abdominal paragangliomas.\nMulticentric, extra-adrenal\nUnknown\nPASS (Pheochromocytoma of the Adrenal gland Scaled Score)\nPheochromocytoma of the adrenal gland scaled score\nHistologic feature\nScore\n(total ≥ 4 is concerning for malignancy)\nPeriadrenal adipose invasion\n+2\n> 3 mitoses/10 high power fields\n+2\nAtypical mitoses\n+2\nNecrosis\n+2\nCellular spindling\n+2\nMarked nuclear pleomorphism\n+1\nCellular monotony\n+2\nLarge nests or diffuse growth\n+2\nHigh cellularity\n+2\nCapsular invasion\n+1\nVascular invasion\n+1\nHyperchromasia\n+1\nInterpretation\n:\nPASS < 4\n: Low risk of malignancy.\nPASS ≥ 4\n: Suggestive of potential malignancy, requiring closer clinical follow-up.\nGAPP (Grading of Adrenal Pheochromocytoma and Paraganglioma)\nGrading system for adrenal pheochromocytoma and paraganglioma (GAPP)\nFeature\nScore (well differentiated, 0 – 2; moderately differentiated,\n3 – 6; poorly differentiated, 7 – 10)\nHistological pattern\nZellballen, 0\nLarge and irregular cell nests, +1\nPseudorosette, +1\nCellularity (number of tumor cells in 10 mm x\n10 mm square at high power magnification)\nLow, < 150, 0\nModerate, 150 – 250, +1\nHigh, > 250, +2\nComedonecrosis\n+2\nCapsular / vascular invasion\n+1\nKi67 %\n< 1%, 0\n1 – 3%, +1\n> 3%, +2\nCatecholamine type\nNonfunctional, 0\nEpinephrine or epinephrine + norepinephrine, 0\nNorepinephrine or norepinephrine + dopamine , +1\nInterpretation\n:\nScore 0-2\n: Well-differentiated, low risk of malignancy.\nScore 3-6\n: Moderately differentiated, intermediate risk.\nScore 7-10\n: Poorly differentiated, high risk of malignancy.\nTry to answer these MCQs\nView this post on Instagram\nA post shared by Pathology MCQs (@pathology_mcqs)\nReferences:\nWHO Classification of Tumors of Endocrine Organs, 5th Edition\n. Lyon: IARC Press, 2022.\nFRCPath Part-1 Histopathology course", "align": "left", "width": 100}, {"id": "522ae27f-eaba-5008-aa4e-a8b9293e75da", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2024/09/IMG_0222.jpeg?resize=1024%2C660&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "85738ec9-47c7-5bb2-95cc-cd91dc6109c7", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2024/09/Blue-Torn-Paper-Coming-Soon-Instagram-Post-9.jpg?resize=1024%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}]'::jsonb,('2024-09-27T22:31:36'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('3771b834-5e2a-5bff-8065-f818f95865d8','IRON METABOLISM - BASICS','iron-metabolism-basics','Iron is an essential mineral that plays a crucial role in various biological processes, including oxygen transport, DNA synthesis, and energy production. Iron Metabolism: Absorption : Iron is primarily absorbed in…','https://pathologymcq.com/iron-metabolism-basics/','https://i0.wp.com/pathologymcq.com/wp-content/uploads/2024/05/IMG_6139.jpeg?resize=1024%2C755&ssl=1',(select id from public.categories where slug='hematopathology'),array(select id from public.categories where slug in ('hematopathology-mcqs-ini-ssdm','hematology')),'published','[{"id": "b7d21b4c-ed2b-5109-8050-ca26170ecad2", "type": "paragraph", "text": "Iron is an essential mineral that plays a crucial role in various biological processes, including oxygen transport, DNA synthesis, and energy production.\nIron Metabolism:\nAbsorption\n: Iron is primarily absorbed in the duodenum and upper jejunum. It exists in two forms in the diet: heme iron (found in animal products) and non-heme iron (found in plant and animal products).\nHeme iron is more readily absorbed (about 15-35%) compared to non-heme iron (about 2-20%).\nTransport\n: Once absorbed,\niron binds to transferrin, a plasma protein that transports iron throughout the body. Transferrin carries iron in its ferric (Fe^3+) form.\nStorage\n: Iron is stored in the body mainly in the form of\nferritin,\nprimarily in the liver, spleen, and bone marrow. Ferritin is a protein that can store thousands of iron atoms in its core.\nUtilization\n: Iron is utilized for various physiological functions, including the synthesis of hemoglobin in red blood cells (RBCs), myoglobin in muscles, and various enzymes involved in energy metabolism and DNA synthesis.\nRecycling\n: Iron is recycled from senescent RBCs by macrophages in the reticuloendothelial system (mainly in the spleen and liver). Hemoglobin from these RBCs is broken down into heme and globin. Heme is further degraded into biliverdin (which is converted to bilirubin) and iron.\nThe iron is then released and either stored in ferritin or transported back into circulation bound to transferrin.\nIron Transport:\nFrom Diet to Bloodstream\n: Iron from the diet is absorbed in the duodenum and upper jejunum. It enters enterocytes (cells lining the intestines) through various transporters, including DMT1 (divalent metal transporter 1). Inside the enterocyte, iron can be stored as ferritin or transported across the basolateral membrane into the bloodstream. Ferroportin is the main transporter responsible for exporting iron out of enterocytes into the bloodstream.\nFrom Macrophages to Bloodstream\n: Macrophages engulf senescent RBCs and break down hemoglobin into its components. Iron released from heme is either stored as ferritin or exported out of the macrophage via ferroportin. Once in the bloodstream, iron binds to transferrin for transport to various tissues and organs.\nRegulation\n: Iron absorption and transport are tightly regulated to maintain iron homeostasis in the body. The hormone hepcidin plays a central role in this regulation by inhibiting ferroportin, thereby reducing iron absorption from the gut and iron release from macrophages when iron levels are high.\nUnderstanding these processes is critical for managing conditions related to iron deficiency or overload, such as anemia or hemochromatosis.\nTry to answer the question below (based on the video):\nQUESTION: False about the mechanism of action of Hepcidin\nA. Hepcidin inhibits ferroporitin\nB. Hepcidin levels rise in iron deficiency anemia\nC. Hepcidin levels can increase in acute and chronic inflammation\nB. Hepcidin regulates iron levels by blocking basolateral iron uptake\nSubmit a form.\nHEMATOPATHOLOGY COURSE", "align": "left", "width": 100}, {"id": "a3e33a19-4543-5af8-96a8-4aeffb3f33b9", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2024/05/IMG_6139.jpeg?resize=1024%2C755&ssl=1", "alt": "", "align": "left", "width": 100}]'::jsonb,('2024-05-13T20:25:09'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('a5d4abde-3dd3-58c8-9c8d-c9e53d936a29','Some differences between Reed- sternberg (RS) cells and RS-like cells','some-differences-between-reed-sternberg-rs-cells-and-rs-like-cells','What are Reed-Sternberg cells or RS-cells? Various types of Reed-Sternberg cells. Many a times RS-like cells may appear in conditions unrelated to Hodgkin’s Lymphomas. It is important to be aware of RS-cells and…','https://pathologymcq.com/some-differences-between-reed-sternberg-rs-cells-and-rs-like-cells/','https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/12/IMG_6216.jpeg?resize=960%2C540&ssl=1',(select id from public.categories where slug='hematopathology'),array(select id from public.categories where slug in ('hematopathology-mcqs-ini-ssdm','hematology')),'published','[{"id": "490d11ee-33bd-5677-b22d-59f2e721affb", "type": "paragraph", "text": "What are Reed-Sternberg cells or RS-cells?\nVarious types of Reed-Sternberg cells.\nMany a times RS-like cells may appear in conditions unrelated to Hodgkin’s Lymphomas. It is important to be aware of RS-cells and their mimics.\nSome clues useful in differentiating RS cells from RS like cells\nFeatures\nRS cells\nRS like- cells\nAssociated conditions\nSeen in HL/composite lymphomas\nMay be seen in high grade lymphomas, rarely in low grade B- or T-cell NHLs\nBackground\nShould be accompanied by characteristic background (fibrosis, inflammatory cells)\nNo characteristic background\nCD 30 expression\nStrong and homogenous CD30\nCD 30 variable expression\nB- cell expression.\nNegative/variable positive for B-cell markers\nB-cell markers more\nhomogenously expressed (CD20, CD79a, PAX-5)\nRS cells vs RS-like cells\nNow on to the most difficult task\nIdentify the True RS-cell\nSubmit a form.\nCorrect answer is B\n. RS cells have a characteristic eosinophilic nucleoli and a polymorphous background. Option A- Horseshoe shaped cells in ALCL. Option C- EBV positive cells associated with EBV positive mucocutaneous ulcer, basophilic nucleoli. Option D: Diffuse large B cell lymphoma.\nRS cells can be identified by routine hematoxylin and eosin staining, however, IHC for CD 15,CD30, CD20 and CD 45 can be useful in their differentiation from RS-like cells.\nJoin our approach based course for useful tips, pitfalls, notes, reporting templates and worksheets- find details below.\nAPPROACH BASED COURSE- ADVANCED HISTOPATHOLOGY AND CYTOLOGY\nClick link for sample materials and details.\nFind summaries below.\nView this post on Instagram\nhttps://www.instagram.com/p/C0zB6SiRgJq/?utm_source=ig_web_copy_link&igshid=MzRlODBiNWFlZA==\nInstagram\nFacebook\nTelegram\nReddit\nWhatsApp\nX\nLinkedIn\nPinterest", "align": "left", "width": 100}, {"id": "0b4b95bf-3d54-5717-91e5-7da052f11361", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/12/IMG_6216.jpeg?resize=960%2C540&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "b467d4b6-6ef4-5916-8f89-5728a6f2b020", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/12/IMG_6219.jpeg?resize=493%2C622&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "7bb9d632-5465-53be-9c2f-23211d6d924d", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/12/IMG_6217.jpeg?resize=960%2C540&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "f2732506-d484-5e9e-96eb-188f6d8b5c48", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/12/IMG_6222.jpeg?resize=875%2C362&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "36bafd41-ba3c-50e9-9a64-f2c37bc230bf", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/12/IMG_6227.jpeg?resize=960%2C540&ssl=1", "alt": "", "align": "left", "width": 100}]'::jsonb,('2023-12-17T12:50:56'::timestamp at time zone 'Asia/Kolkata')) on conflict 