insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('79e03dd9-f51d-5d31-b7f1-e231a678951c','Mushroom shaped red blood cells','mushroom-shaped-red-blood-cells','MUSHROOM SHAPED RED CELLS ARE SEEN IN? Try to answer this multiple choice question Heriditary spherocytosis with which mutation shows “mushroom or pincer” shaped red cells in peripheral smear? OPTION A. Band 3 B.…','https://pathologymcq.com/mushroom-shaped-red-blood-cells/','https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/10/gr1.jpg?resize=300%2C297&ssl=1',(select id from public.categories where slug='hematopathology'),array(select id from public.categories where slug in ('hematology')),'published','[{"id": "6ae1576e-cd2d-5984-828f-bdec311fe53e", "type": "paragraph", "text": "MUSHROOM SHAPED RED CELLS ARE SEEN IN?\nTry to answer this multiple choice question\nHeriditary spherocytosis with which mutation shows “mushroom or pincer” shaped red cells in peripheral smear?\nOPTION\nA. Band 3\nB. Protein 4.2\nC. Ankyrin\nD. Spectrin\nCORRECT ANSWER\nAnswer is Option A: Band 3\nReference:\nhttps://imagebank.hematology.org/image/63928/mushroom-shaped-red-blood-cell", "align": "left", "width": 100}, {"id": "9913d912-8a74-5ccb-ac5c-728cbdf2fa7e", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/10/gr1.jpg?resize=300%2C297&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "f5916baa-1dc9-5407-b6a8-a2a1dfbc9862", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2022/10/Copy-of-Sickle-Cell-Anemia-by-Slidesgo.jpg?resize=683%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}]'::jsonb,('2022-10-09T00:00:57'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('498e5e8f-0fe6-5803-b452-1e2d39df40a2','HEMOPHILIA B LEYDEN- A rare form of FIX deficiency','hemophilia-b-leyden-a-rare-form-of-fix-deficiency','HEMOPHILIA B LEYDEN is a rare form of FIX deficiency Here are some key points to be noted regarding Hemophilia B Leyden. It is a rare form of FIX deficiency, hemophilia B Leyden, undergoes postpubertal phenotypic…','https://pathologymcq.com/hemophilia-b-leyden-a-rare-form-of-fix-deficiency/',NULL,(select id from public.categories where slug='hematopathology'),array(select id from public.categories where slug in ('hematology')),'published','[{"id": "4e2890ee-d6a5-5f58-9aab-16bb19e3a0c2", "type": "paragraph", "text": "HEMOPHILIA B LEYDEN is a rare form of FIX deficiency\nHere are some key points to be noted regarding Hemophilia B Leyden.\nIt is a rare form of\nFIX deficiency, hemophilia B Leyden, undergoes postpubertal phenotypic resolution.\nPatients with this condition present with hemophilia B in early childhood, with FIX activity ranging from less than 1% to 13% of normal.\nPlasma levels rise to as high as 70% of normal after the onset of puberty with resolution of bleeding complications.\nMutations in hemophilia B Leyden have been identified in the\npromoter region of the FIX gene,\nwithin which a consensus sequence for steroid receptor binding is located.\nREVIEW QUESTION- A QUESTION FROM DM HEMATOPATHOLOGY PGIMER ENTRANCE\nhttps://www.pinterest.com/pin/1140114461886804954/sent/?invite_code=7a8338375f02443cb32b97c4693936ac&sender=1140114599324959776&sfo=1\nCLICK TO REVEAL THE ANSWER\nANSWER is C: Steroid receptor is involved in the pathogenesis.", "align": "left", "width": 100}]'::jsonb,('2021-07-24T17:13:03'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('4d92586f-aee6-5c7a-947a-7843ba8af028','MYH-9 associated congenital macrothrombocytopenias','myh-9-associated-congenital-macrothrombocytopenias','MYH 9 associated congenital macrothrombocytopenias are important in an examination point of view. Let’s look at different types, key differences and some multiple choice questions. A diverse group of autosomal…','https://pathologymcq.com/myh-9-associated-congenital-macrothrombocytopenias/',NULL,(select id from public.categories where slug='hematopathology'),array(select id from public.categories where slug in ('hematology')),'published','[{"id": "f353fc30-50b5-5ab4-8e5a-0e8947175398", "type": "paragraph", "text": "MYH 9 associated congenital macrothrombocytopenias\nare important in an examination point of view. Let’s look at different types, key differences and some multiple choice questions.\nA diverse group of autosomal dominant syndromes, referred to as MYH9-related macrothrombocytopenias, include the\nMay-Hegglin anomaly,\nFechtner syndrome,\nEpstein syndrome, and\nSebastian syndrome\nThese share features of increased platelet size, cytoplasmic inclusions in leukocytes (Döhle bodies), and premature release of platelets. These entities arise from mutations in MYH9 encoding the nonmuscle myosin heavy chain IIA, a contractile cytoskeletal protein. All of the MYH-9 syndromes have macrothrombocytopenia; other features such as nephritis, sensorineural deafness, and cataracts serve to distinguish them.\nFIND A QUICK DIFFERENTIAL DIAGNOSIS OF ALL MYH 9 ASSOCIATED DISORDERS\nhttps://www.pinterest.com/pin/1140114461886736454/sent/?invite_code=5e37aa7fec304ba496a02e95f4e9949f&sender=1140114599324959776&sfo=1\nHEMATOPATHOLOGY COURSE\nConcise Hematopathology Notes- Hard Copies", "align": "left", "width": 100}]'::jsonb,('2021-07-15T15:10:06'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
