insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('14293fe5-a7d7-5445-9c04-5c9addba708d','Pathology Daily MCQ Contest','pathology-daily-mcq-contest','Here is a fun contest to learn pathology and win exciting rewards as well. CONTEST COMPLETE Winners of the Pathology daily MCQ contest User 1st Prize WINNER User 2nd Prize WINNER User 3rd prize WINNER WHO CAN…','https://pathologymcq.com/pathology-daily-mcq-contest/','https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/06/96946457-0EE8-491B-95B4-51D41E39B0EB.jpeg?resize=715%2C396&ssl=1',(select id from public.categories where slug='general'),'{}'::uuid[],'published','[{"id": "cdd8f266-1045-51d9-985e-aee059287870", "type": "paragraph", "text": "Here is a fun contest to learn pathology and win exciting rewards as well.\nCONTEST COMPLETE\nWinners of the Pathology daily MCQ contest\nUser\n1st Prize WINNER\nUser\n2nd Prize WINNER\nUser\n3rd prize WINNER\nWHO CAN PARTICIPATE?\nPathology residents\nPractising pathologists\nAnyone with interest in pathology\nHOW TO PARTICIPATE?\nStep 1: Login to your Pathology MCQ account (Register in case you do not have one and use the same account for all your entries)\nUsername or E-mail\n*\nPassword\n*\nOnly fill in if you are not human\nKeep me signed in\nRegister\nForgot your password?\nHOW ARE REWARD POINTS CALCULATED?\nPoints for each attempt =1\nPoints for every correct answer = 3\nCumulative reward point for every user will be calculated based on number of attempts and correct answers.\nIn case of a tie , time taken to answer a question and   time from answering the questions after it’s live will be taken into account.\nWHAT WILL I WIN?\nTen users with the highest reward points have the opportunity to with exciting prizes\n1st – 60 $ worth gift coupons\n2nd- 50 $ worth gift coupons\n3rd- 40 $ worth gift coupons\n4th and 5th-  15 $ worth Gift coupons\n6th- 10th- Gifts\nHAVE QUESTIONS ?