insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('4e66b84b-4031-5564-827c-b8a256ee6a3b','Morphology and Immunohistochemical features of trophoblastic cell types','morphology-and-immunohistochemical-features-of-trophoblastic-cell-types','Find a summary of morphology and Immunohistochemical features of trophoblastic cell types Solve the MCQ related to this topic Gestational trophoblastic diseases','https://pathologymcq.com/morphology-and-immunohistochemical-features-of-trophoblastic-cell-types/','https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/05/D466024B-18F1-45C5-9B63-D8884D9A1CF1.jpeg?resize=1024%2C728&ssl=1',(select id from public.categories where slug='general'),'{}'::uuid[],'published','[{"id": "8fab50b6-a77b-5f2a-9847-843d81a3ee51", "type": "paragraph", "text": "Find a summary of morphology and Immunohistochemical features of trophoblastic cell types\nSolve the MCQ related to this topic\nGestational trophoblastic diseases", "align": "left", "width": 100}, {"id": "2c48a879-511b-527c-8df1-5bb0c26b50af", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/05/D466024B-18F1-45C5-9B63-D8884D9A1CF1.jpeg?resize=1024%2C728&ssl=1", "alt": "", "align": "left", "width": 100}]'::jsonb,('2023-05-15T17:26:04'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('929793f6-17f4-5dda-a340-ac8f91d8d2f6','Carney’s confusion','carneys-confusion','Ever been confused about the three carney’s- Carney’s triad, Carney’s complex and Carney stratakis syndrome, here are few pointers to remember them easily. Carney’s triad: As the name signifies, Carney’s triad is a…','https://pathologymcq.com/carneys-confusion/','https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/04/21D03106-2DFB-476F-A9CE-442A531EE5D1.jpeg?resize=1024%2C932&ssl=1',(select id from public.categories where slug='general'),'{}'::uuid[],'published','[{"id": "e6663290-5dda-58c4-b3ff-fca63b307ccf", "type": "paragraph", "text": "Ever been confused about the three carney’s- Carney’s triad, Carney’s complex and Carney stratakis syndrome, here are few pointers to remember them easily.\nCarney’s triad:\nAs the name signifies, Carney’s triad is a combination of three neoplasms.\nPulmonary chordoma\nGastrointestinal stromal tumor involving the stomach\nExtra- adrenal paraganglioma.\nUsually occurs in young individuals, especially young females. Genetics associated are unknown\n2.\nCarney complex:\nCarney complex is a disorder characterized by an increased risk of several types of tumors. Affected individuals also usually have changes in skin coloring (pigmentation). Signs and symptoms of this condition commonly begin in the teens or early adulthood.\nCarney complex is autosomal dominant and is associated with PRKARIA germline mutation\n3.\nCarney- stratakis syndrome also known as Carney dyad:\nIt is associated with familial paragangliom and gastrointestinal stromal tumor. Germline mutations in SDHB, SDHC and SDHD are observed\nRemember: 2 names, carney and stratakis, dyad- 2 conditions .\nSUMMARY\nSOME MCQS\nCarney", "align": "left", "width": 100}, {"id": "f111253d-4327-5d34-8a85-2fd5ae28830f", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/04/21D03106-2DFB-476F-A9CE-442A531EE5D1.jpeg?resize=1024%2C932&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "860fb5c9-2530-5cca-9d64-77da9beed350", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/04/A1F8B400-EE02-4910-AAF6-1176E0E0CC1D.jpeg?resize=842%2C595&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "4da1dc40-1697-574a-8d82-290be7a8b856", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/04/89E1E40A-5A32-465E-BF96-659246B665A2.jpeg?resize=958%2C450&ssl=1", "alt": "", "align": "left", "width": 100}]'::jsonb,('2023-04-06T16:10:01'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('706a56de-dd0f-564c-adc3-e9ec23082177','P53 Signature Lesion in Ovarian Tumors: Histological Features and Progression','summary-of-precursor-lesions-of-serous-ovarian-carcinoma','Precursor lesions of high grade serous ovarian tumors. Their progression and histological features summarized. View this post on Instagram A post shared by Pathology MCQs (@pathology_mcqs) Try to answer this MCQ –…','https://pathologymcq.com/summary-of-precursor-lesions-of-serous-ovarian-carcinoma/','https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/01/Pathology-thatha-templates-4.jpg?resize=692%2C1024&ssl=1',(select id from public.categories where slug='general'),'{}'::uuid[],'published','[{"id": "ba793be9-b8fd-59cd-bddd-f4e9e36aa5d8", "type": "paragraph", "text": "Precursor lesions  of high grade serous ovarian tumors. Their progression and histological features summarized.\nView this post on Instagram\nA post shared by Pathology MCQs (@pathology_mcqs)\nTry to answer this MCQ – Based on the topic\nCLICK TO REVEAL THE CORRECT ANSWER\nThis lesion is p53 signature lesion.\nAnswer is D\nEpithelium has a normal histology\nMutant pattern p53 staining with at least 12 cells in a row\nLow ki67 index\nType I vs. Type II Serous Ovarian Cancers: Pathogenesis and Progression\nFemale genital tract pathology multiple choice questions- PART 1 ( Ovary)\nFOR MORE MCQs, High yield notes and Flash cards- JOIN US in the course\nNEET-SS/ DM ONCOPATHOLOGY ONLINE COURSE 2.0v\nFRCPath Part-1 Histopathology Course", "align": "left", "width": 100}, {"id": "c51d5025-0f27-5d6a-850b-7f0a6f6969ea", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/01/Pathology-thatha-templates-4.jpg?resize=692%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}]'::jsonb,('2023-02-09T02:19:07'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
