insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('db46f392-27cb-59f7-b67b-6c4d66650970','FRCPATH Part-1 - Mock Tests','frcpath-part-1-free-mock-test','Are you gearing up for the FRCPATH Part -1 exam? Checkout FRCPath- Part -1 Histopathology Complete Mock tests- Comprising of 4 complete mock tests. These mock tests are readily available for our course subscribers…','https://pathologymcq.com/frcpath-part-1-free-mock-test/',NULL,(select id from public.categories where slug='frcpath-part-1-histopathology'),array(select id from public.categories where slug in ('daily-mcqs')),'published','[{"id": "a88a606b-21c6-597a-a1a7-dda74d19a391", "type": "paragraph", "text": "Are you gearing up for the\nFRCPATH\nPart\n-1 exam?\nCheckout FRCPath- Part -1 Histopathology Complete Mock tests- Comprising of 4 complete mock tests.\nThese mock tests are readily available for our course subscribers\nFRCPath- Part -1 Histopathology Complete Mock tests", "align": "left", "width": 100}]'::jsonb,('2024-09-08T23:21:12'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('f8a0a61c-c21f-58c6-bda5-69f8faaea144','🧾 Gross Pearls: Anatomy & Surgical Resection of the Rectum','%f0%9f%a7%be-gross-pearls-anatomy-surgical-resection-of-the-rectum','Why this matters: Accurate orientation of rectal specimens and understanding of peritoneal relations underpin proper grossing, staging, and surgical decision-making (LAR vs APR). 📍 Gross Anatomy of the Rectum The…','https://pathologymcq.com/%f0%9f%a7%be-gross-pearls-anatomy-surgical-resection-of-the-rectum/','https://i0.wp.com/pathologymcq.com/wp-content/uploads/2025/10/1.jpg?resize=819%2C1024&ssl=1',(select id from public.categories where slug='grossing'),'{}'::uuid[],'published','[{"id": "d34c6742-66a6-557f-8cb7-4ead6e3cc9ea", "type": "paragraph", "text": "Why this matters:\nAccurate orientation of rectal specimens and understanding of peritoneal relations underpin proper grossing, staging, and surgical decision-making (LAR vs APR).\n📍 Gross Anatomy of the Rectum\nThe rectum extends from the sigmoid colon to the anal canal, enveloped by the mesorectum.\nIts division into\nupper, middle, and lower thirds\nis based on\nperitoneal reflections\n.\nCaption:\nGross orientation of the rectum and mesorectal envelope.\n⚔️ Surgical Procedures: APR vs LAR\nThe choice of operation depends on\ntumor height\n,\nsphincter involvement\n, and\npatient factors\n.\nComparison Table\nFeature\nLow Anterior Resection (LAR)\nAbdominoperineal Resection (APR)\nGoal\n→ Sphincter-sparing\n→ Removes rectum + anus + sphincter\nAnastomosis\n→ Rectum resected; bowel reconnected\n→ Permanent colostomy\nTypical Indication\n→ Mid/upper rectal tumors (≥ 4 cm above sphincter)\n→ Very low tumors, sphincter involvement, or when continence/margins not preserved\nCaption:\nLAR vs APR — specimen comparison.\n🧩 Anatomy of APR Specimen\nAnterior View\nStructures you should identify:\n→ Appendices epiploicae\n→ Tinea coli\n→ Mesorectal envelope\nCaption:\nAPR (anterior) with key structures labeled.\nLateral View\nRegional divisions to label confidently based on the mesorectum\n→ Upper rectum\n→ Middle rectum\n→ Lower rectum\n→ Anal canal\nCaption:\nAPR (lateral) with rectal thirds and anal canal.\n🧩 Anatomy of LAR Specimen\nLAR preserves the sphincter with restoration of bowel continuity (anastomosis).\nThe posterior view is ideal for marking\nupper/middle/lower\nthirds.\nCaption:\nLAR (posterior) showing rectal thirds with intact sphincter complex.\n📚 Peritoneal Relations of the Rectum\nThese relations guide both\npathology staging\nand\nsurgical planes of dissection\n.\nPeritoneal Coverage by Segment\nRectal Segment\nPeritoneal Covering\nUpper third\n→ Peritoneum anteriorly and laterally; posterior surface by mesorectum\nMiddle third\n→ Peritoneum only on the anterior surface; lateral/posterior by mesorectum\nLower third\n→ Entirely extraperitoneal; all surfaces by mesorectum\nCaption:\nAnterior and lateral APR views with peritoneal reflection levels.\n📊 Cross-Sectional Understanding\nUse cross-sections to internalize coverage patterns at each level.\nCross-Section Table\nSection\nAnterior\nLateral\nPosterior\nUpper rectum\n→ Peritoneum\n→ Peritoneum\n→ Mesorectum\nMiddle rectum\n→ Peritoneum\n→ Mesorectum\n→ Mesorectum\nLower rectum\n→ Mesorectum\n→ Mesorectum\n→ Mesorectum\nCaption:\nCross-sections (peritoneum vs mesorectum) for upper, middle, and lower rectum.\n✨ Key Takeaways\n→ Rectal thirds are defined by\nperitoneal relationships\n(not arbitrary distances).\n→\nLAR\n: sphincter-sparing with anastomosis;\nAPR\n: removes anus + sphincter → permanent colostomy.\n→\nMesorectal envelope integrity\nis critical for oncologic outcomes and staging.\n→ Always document\norientation\n(anterior/lateral/posterior),\nperitoneal reflections\n, and\nquality of the mesorectum\nin gross reports.\n🎮 Challenge Mode: Rectum Anatomy & Surgery (5 Qs)\nScore:\n0\npts\nStreak:\nx1\nLifeline:\n50-50 ×\n1\nQ1. Which statement best distinguishes LAR from APR?\nLAR removes anus and sphincter; APR preserves them\nLAR is sphincter-sparing with anastomosis; APR removes rectum + anus + sphincter → colostomy\nBoth always end with permanent colostomy\nAPR is preferred for mid/upper rectal tumors\nHint\n50-50\nValue: 100 pts\nThink about continence preservation and where the tumor sits relative to the sphincter.\nAPR sacrifices the sphincter (permanent colostomy). LAR preserves sphincter function when margins are safe.\nQ2. In the\nmiddle third\nof the rectum, which surfaces are covered by peritoneum?\nAnterior only\nAnterior and lateral\nPosterior only\nNone\nHint\n50-50\nValue: 120 pts\nUpper = anterior + lateral; middle = ?; lower = extraperitoneal.\nOnly the anterior surface retains peritoneum; lateral and posterior are mesorectal.\nQ3. The\nmesorectal envelope\nis:\nThe peritoneal lining of the rectum\nPerirectal fat with vessels & lymph nodes removed in TME\nThe muscularis propria\nAnal sphincter complex\nHint\n50-50\nValue: 150 pts\nIt’s what surgeons aim to remove intact during TME.\nThe mesorectum is the perirectal fatty package containing nodes and vessels; its integrity predicts outcomes.\nQ4. Which statement about the\nlower third\nof the rectum is TRUE?\nCovered by peritoneum on all surfaces\nCompletely extraperitoneal; surrounded by mesorectum\nOnly the posterior surface is peritonealized\nHas peritoneum anteriorly and laterally\nHint\n50-50\nValue: 140 pts\nContrast it with the upper third.\nLower third has no peritoneal covering at all; all surfaces are mesorectal.\nQ5. Tumor 5 cm above the anal verge with threatened sphincter—most appropriate operation?\nAPR (abdominoperineal resection)\nLAR with primary anastomosis\nRight hemicolectomy\nLocal transanal excision for all cases\nHint\n50-50\nValue: 170 pts\nIf continence or safe margins can’t be preserved, which surgery sacrifices the sphincter?\nVery low tumors or sphincter involvement → APR with permanent colostomy is standard.\nCheck Answers\nReset\nScoring:\nBase points × streak (x1, x2, x3…). 50-50 costs 20% of that question’s points.\nView this post on Instagram\nA post shared by Pathology MCQs (@pathology_mcqs", "align": "left", "width": 100}, {"id": "4c9834bf-f1b1-539e-acd2-feef7143c3e4", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2025/10/1.jpg?resize=819%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "91f83453-c451-5e71-ac5f-98ca771f0d20", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2025/10/3-1.jpg?resize=819%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "c0ab52f7-f980-5e4e-9079-ad29d42f302a", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2025/10/4-3.jpg?resize=819%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "dd360cde-eee0-5332-83ab-bd1eb9fa11d9", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2025/10/5.jpg?resize=819%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "61a729d3-ca57-5a74-802e-185f011b12a4", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2025/10/6.jpg?resize=819%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "1eaf0e36-0ed3-5dae-928d-2167a9780d9f", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2025/10/7.jpg?resize=819%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "27de2517-87ca-549f-b773-d35e6fbc761e", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2025/10/8.jpg?resize=819%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}]'::jsonb,('2025-10-05T22:10:52'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('6e6aba94-e660-5dba-a628-34726af4eac0','Commonly Encountered Artifacts in Cervical Cytology','commonly-encountered-artifacts-in-cervical-cytology','Cervical cytology plays a crucial role in diagnosing various gynecologic conditions, especially in screening for cervical cancer. However, artifacts in cytology slides can sometimes complicate interpretations,…','https://pathologymcq.com/commonly-encountered-artifacts-in-cervical-cytology/','https://i0.wp.com/pathologymcq.com/wp-content/uploads/2024/11/Copy-of-Copy-of-Neutral-Minimalist-Business-Tips-Instagram-Post-Carousel.zip-2.jpeg?resize=1024%2C1024&ssl=1',(select id from public.categories where slug='cytology'),'{}'::uuid[],'published','[{"id": "dbb3f549-f445-59fb-b92e-ea810d81b720", "type": "paragraph", "text": "Cervical cytology plays a crucial role in diagnosing various gynecologic conditions, especially in screening for cervical cancer. However, artifacts in cytology slides can sometimes complicate interpretations, leading to potential misdiagnosis. Here, we explore some of the commonly encountered artifacts in cervical cytology, which every pathologist should be aware of.\n1. Cornflake Artifact\nThis common brown artifact appears due to air bubbles that form when xylene dries before the slide is mounted. Named for its resemblance to cornflakes, this artifact can be mistaken for pathological findings if not identified correctly. It highlights the importance of proper slide preparation and mounting techniques to avoid diagnostic errors.\nCause:\nAir bubbles due to drying of xylene before mounting\nAppearance:\nBrown, flaky structures on the slide\nPreventive Tip:\nEnsure slides are adequately mounted to avoid air bubble formation.\n2. Cocklebur Artifact\nCocklebur artifacts, also known as pseudoactinomycotic radiating arrays, are crystalline material surrounded by histiocytes. They are sometimes associated with pregnancy and can be mistaken for\nActinomyces\ninfection due to their similar radiating appearance.\nAssociations:\nOften seen in pregnancy\nMisinterpretation:\nCan be confused with\nActinomyces\nIdentification Tip:\nNote the radiating crystalline structure and absence of true fungal elements.\n3. Glycogenation\nGlycogenated squamous cells, also called “navicular cells,” display a golden-yellow hue due to glycogen accumulation. This phenomenon is typically associated with pregnancy and the post-ovulatory phase. In some cases, glycogenated cells may resemble low-grade squamous intraepithelial lesion (LSIL), leading to possible misinterpretation.\nAssociations:\nPregnancy, post-ovulatory phase\nMisinterpretation:\nMay resemble LSIL due to similar cellular changes\nIdentification Tip:\nLook for the golden-yellow glycogen deposits in the cells.\n4. Carpet Beetle Larva\nCarpet beetle larvae hairs, commonly found in textiles, can sometimes appear on cytology slides, especially in cases involving tampon use. This artifact can be mistaken for fungal infections, such as\nCandida\n.\nAssociations:\nTampon use\nMisinterpretation:\nOften misinterpreted as\nCandida\nIdentification Tip:\nObserve the characteristic hair-like structures to differentiate it from fungal elements.\n5. Trichromes\nTrichromes are plant-derived contaminants that appear as large, star-like structures on cytology slides. These structures, often found in the context of plant exposure, can be mistaken for\nCandida\ninfections due to their unique morphology.\nCause:\nPlant epidermal appendages\nAppearance:\nLarge, star-like structures\nMisinterpretation:\nCan be confused with\nCandida\nIdentification Tip:\nRecognize the characteristic structure to avoid confusion with fungal organisms.\nFor more like these\n:\nGET OUR CYTOPATHOLOGY NOTES\nReferences\nCibas, E. S., & Ducatman, B. S. (2014).\nCytology: Diagnostic Principles and Clinical Correlates\n(4th ed.). Philadelphia, PA: Elsevier Saunders.\nMitchell, M. L., & Medley, R. A. (2013).\n“Recognition of Artifacts and Contaminants in Cervical Cytology: A Practical Approach.”\nJournal of Cytology\n, 30(1), 27-32", "align": "left", "width": 100}, {"id": "344eedae-3c3c-583d-a250-d25c6909e6bb", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2024/11/Copy-of-Copy-of-Neutral-Minimalist-Business-Tips-Instagram-Post-Carousel.zip-2.jpeg?resize=1024%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "6adc7c82-3995-5afd-9232-28ee0f550283", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2024/11/Copy-of-Copy-of-Neutral-Minimalist-Business-Tips-Instagram-Post-Carousel.jpg?resize=1024%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "c358c9f1-9af5-523a-824a-530a71a66744", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2024/11/Copy-of-Copy-of-Neutral-Minimalist-Business-Tips-Instagram-Post-Carousel.zip-4.jpeg?resize=1024%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "f3b7299b-2374-581a-b5a7-0f7f552c128d", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2024/11/Copy-of-Copy-of-Neutral-Minimalist-Business-Tips-Instagram-Post-Carousel.zip-5.jpeg?resize=1024%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "98dcada4-e071-57c5-b7c5-56091b4b7baf", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2024/11/Copy-of-Copy-of-Neutral-Minimalist-Business-Tips-Instagram-Post-Carousel.zip-6.jpeg?resize=1024%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "20970969-8395-5dc1-9e71-7b12949564f4", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2024/11/Copy-of-Copy-of-Neutral-Minimalist-Business-Tips-Instagram-Post-Carousel-2.jpg?resize=1024%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}]'::jsonb,('2024-11-03T00:28:29'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('7b4bd54a-e242-5c9f-89e2-81c447c273af','CYTOLOGY SPECIMEN ADEQUACY CRITERIA','cytology-specimen-adequacy-criteria','A summary of adequacy criteria for various cytology specimens. CYTOLOGY SPECIMENS 1. Cervical cytology 2. Anal cytology 3. Fine needle aspiration cytology for thyroid nodules 4. Urinary cytology 5. Salivary gland…','https://pathologymcq.com/cytology-specimen-adequacy-criteria/','https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/02/B057E293-8AEB-4DF1-B2A0-3D4B07E1BC77.jpeg?resize=1024%2C504&ssl=1',(select id from public.categories where slug='cytology'),'{}'::uuid[],'published','[{"id": "f1e77b69-f8bf-5c7d-9f25-ccb5cb879186", "type": "paragraph", "text": "A summary of adequacy criteria for various cytology specimens.\nCYTOLOGY SPECIMENS\n1. Cervical cytology\n2. Anal cytology\n3. Fine needle aspiration cytology for thyroid nodules\n4. Urinary cytology\n5. Salivary gland cytology\n6. Pancreaticobiliary cytology\n7. Serous fluid cytology\n8. Sputum cytology\n9. Fine needle aspiration cytology of breast\n10. Fine needle aspiration biopsy of breast\n11. Summary\n12. Multiple choice questions on this topic\nCERVICAL CYTOLOGY:\nAdequacy criteria: based on 2014 Bethesda system of reporting cervical cytology\nSatisfactory:\nAdequate number of well visualized or preserved squamous or squamous metaplastic cells\nConventional smear:\nminimum 8,000 – 12,000 cells\nLiquid based preparation:\nminimum 5,000 cells\nWoman’s postchemotherapy, radiotherapy, postmenopausal, atrophic changes or posthysterectomy may have < 5,000 cells and be deemed adequate at laboratory’s discretion (if > 2,000 cells)\nException: adequate if any abnormal cells are present\nUnsatisfactory\n:\nMore than 75% of cells obscured by inflammation, bacteria or interfering substances (lubricants and blood)\n50 – 75% of cells obscured, include a disclaimer describing how and the percentage of cells obscured\n2. ANAL CYTOLOGY\nSpecimen adequacy is based primarily upon specimen cellularity and morphological quality of the sample.\nAs outlined in The Bethesda System,\nA minimum cellularity for\nconventional anal-rectal cytology smears is 2,000 to 3,000\nnucleated squamous cells (image) for conventional smears,\n1–2 nucleated squamous cells per high power field (hpf) for ThinPrep specimens,\nand\n3–6 nucleated squamous cells per hpf for SurePath specimens\n.\nSpecimens composed primarily of anucleate squamous cells and specimens that do not meet minimum criteria for cellularity should be considered unsatisfactory for evaluation; provided that no abnormal cells are identified, no diagnostic interpretation/result should be rendered for such specimens.\nObscuring factors such as fecal material, bacteria, and inflammation may hinder evaluation, and when the majority of nucleate squamous cells are obscured, specimens should be considered unsatisfactory for evaluation.\nWhile the\npresence of a transformation zone component is not required for a satisfactory specimen\n, presence or absence of glandular columnar cells should be noted.\n3. FINE NEEDLE ASPIRATION CYTOLOGY OF THYROID NODULES\nAdequacy criteria based on The Bethesda system for reporting thyroid cytopathology 2017 2nd edition.\nFNA smear should contain ≥ 6 groups of well visualized follicular cells (≥ 10 cells/group), preferably on a single slide\nExceptions (a minimum number of follicular cells is not required)\n✅Solid nodules with cytologic atypia, which qualify into categories III – VI\n✅Solid nodules with inflammation are considered benign\n✅Only numerous inflammatory cells\n✅Lymphocytic thyroiditis, thyroid abscess or granulomatous thyroiditis\n✅Nodules with abundant colloid are placed in the benign category even in the absence of follicular epithelium\n4. URINARY CYTOLOGY\nAccording to The Paris System for Reporting Urinary Cytology\nVoided urine:\n>30 ml without non-urothelial features obscuring urothelial morphology\nInstrumented urine\n:  2600 cells or at least 20 cells in 10 HPF may be taken as adequacy criteria.\n5. SALIVARY GLAND CYTOLOGY\nAccording to\nThe Milan System for Reporting Salivary Gland Cytopathology (MSRSGC)\n:\nMore than 60 lesional cells\nare required  for a cytologic diagnosis.\nAny atypical cells or sign of features such as mucin is also considered adequate.\n6. PANCREATICO-BILIARY CYTOLOGY\nAccording to The\nPapanicolaou Society of Cytopathology (PSC)\ndeveloped in 2014\nContains adequate cellular or extracellular tissue to evaluate or define a lesion that is identified on imaging\nOnly GI contamination, or benign pancreatic tissue indicates missed lesion and is considered non diagnostic.\nNOTE: MUCIN is considered adequate in MILAN( Salivary gland cytology) but not in pancreatico-biliary cytology.\n7. SEROUS FLUID CYTOLOGY\nAccording to The international system standardized reporting of serous fluid cytology\nVolume of fluid:\nThere is no specific cutoff but volume\n>50 mL to 75ml is considered adequate\nCellularity\n:  There is no definitive criteria of number of mesothelial cells for adequacy and the criteria might vary depending on the pathologic process.\nQuality of preparation:\npoor cell preservation, degeneration, hemorrhage, artifacts and contaminants can impair interpretation and is considered inadequate,\n8. SPUTUM CYTOLOGY\nPresence of alveolar macrophages are a must for sputum cytology specimens to be deemed adequate\n9. FINE NEEDLE ASPIRATION CYTOLOGY OF BREAST\n✅No definite criteria for adequacy in breast FNA cytology\n✅MD Anderson Cancer Center Group proposed that 4 – 6 well visualized cell groups with 10 or more cells / flat sheets as an adequacy criteria.\n✅Samples that lack epithelial cells are considered inadequate in general\n✅If the lesion is suspected to be lipoma or fat necrosis, the absence of epithelial clusters doesn’t indicate inadequacy\n10. FINE NEEDLE ASPIRATION BIOPSY OF BREAST\nAccording to Yokohama system for reporting Fine needle aspiration biopsy\n✅If there is a mass lesion on palpation or imaging, which does not decrease in size on FNAB, the presence of seven tissue fragments, each of 20 or more epithelial cells, are suggested as a measure of adequacy.\n11\n.\nSUMMARY OF CYTOLOGIC ADEQUACY CRITERIA- ALL SPECIMENS\nView this post on Instagram\nA post shared by Pathology MCQs (@pathology_mcqs)\n12. MULTIPLE CHOICE QUESTIONS\nWelcome to your Cytology adequacy criterias-quiz\n1.\nPresence of which of the following is required in an adequate broncho alveolar lavage (BAL) specimen?\nLymphocytes\nCiliated epithelial cells\nAlveolar macrophages\nAll of the above.\nNone\n2.\nThe adequacy of a sputum sample is established by finding which of the following cells in the specimen?\nA) Ciliated columnar cells\nB) Squamous cells\nC) Pulmonary macrophages\nD) Goblet cells\nNone\n3.\nAccording to bethesda 2014 what is minimum cellularity required for a conventional PAP smear to be deemed adequate?\nA. 200-300\nB. 8000-12000\nC. 5000\nD. 1000\nNone\n4.\nAccording to Bethesda 2014 what is the minimum cellularity required in a liquid based preparation\nA. 5000\nB. 1000\nC. 2000\nD. 4000\nNone\n5.\nCellularity of a conventional PAP smear is calculated on the basis of which of the following cells.\nA. Preserved squamous cells\nB. Squamous metaplastic cells\nC. Both\nD. Endocervical cells\nNone\n6.\nIn which of the following conditions a cellularity of < 5000 cells is considered adequate in a liquid based preparation?\nA. Post chemo or radiotherapy\nB. Post menopausal females\nC. Post hysterectomy\nD. All of the above\nNone\n7.\nExample of an unsatisfactory PAP smear is?\nA. A smear showing high grade squamous intraepithelial lesion\nB. Absence of endocervical cells\nC. Only 25% of the cells are visible and rest are obscured by blood or bacteria\nD. Presence of lymphocytic aggregates\nNone\n1\n2\n3\n4\n5\n6\n7\nTime''s up\nCancel\nYou cannot switch tabs while taking this quiz!\nYou are not allowed to switch tabs violation has been recorded.\nResume Quiz\nyou cannot minimize full screen mode!\nYou are not allowed to minimize full screen while taking this quiz, violation has been recorded.\nResume Quiz\nAccess denied! To begin the quiz, please grant this quiz access to your camera.\nClose Popup\nAny additions and comments are welcome\nReferences\nhttps://www.ncbi.nlm.nih.gov/pmc/articles/PMC9168399/\nhttps://pubmed.ncbi.nlm.nih.gov/29091573/\nhttps://www.ncbi.nlm.nih.gov/pmc/articles/PMC8489693/\nJOIN OUR APPROACH BASED COURSE TO KNOW MORE ABOUT THE APPROACH TO LESIONS IN CYTOLOGY\nApproach based course Histopathology and cytology", "align": "left", "width": 100}, {"id": "774dfc1d-ab9d-509f-afb0-fd1af18305c3", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/02/B057E293-8AEB-4DF1-B2A0-3D4B07E1BC77.jpeg?resize=1024%2C504&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "e36ba1ac-a539-57f0-afc3-623ecfd31f7b", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/02/9C7D870B-E255-4A71-8425-E86E7B892FC4.jpeg?resize=265%2C190&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "2b885f68-e618-5b8a-a7c1-7e0864529b94", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/02/E37DC7F1-00AA-4897-971D-D57F99EA4EAD.jpeg?resize=960%2C540&ssl=1", "alt": "", "align": "left", "width": 100}, {"id": "a515d254-a140-5b05-87b9-927928d96f3d", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/02/1F3A4F55-0E7A-4DB9-9B3E-73E072F50CA5.jpeg?resize=1024%2C618&ssl=1", "alt": "", "align": "left", "width": 100}]'::jsonb,('2023-02-12T08:25:58'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
