insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('f49c3fc8-7495-5ee9-b430-f8cd4e723558','Pathology puzzle','pathology-puzzle','Try to solve this pathology puzzle based on Hematoxylin and eosin staining. Key points in hematoxylin eosin staining with practise mcqs https://pathologymcq.com/2021/04/14/points-hematoxylin-and-eosin-staining/…','https://pathologymcq.com/pathology-puzzle/','https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/04/6F8836E1-9C95-4A74-9C4E-47EB78ABCA47.jpeg?resize=679%2C1024&ssl=1',(select id from public.categories where slug='histotechniques'),array(select id from public.categories where slug in ('staining')),'published','[{"id": "d9e41b4b-5938-54a8-b77d-f1420b84e55c", "type": "paragraph", "text": "Try to solve this pathology puzzle based on Hematoxylin and eosin staining.\nKey points in hematoxylin eosin staining with practise mcqs\nhttps://pathologymcq.com/2021/04/14/points-hematoxylin-and-eosin-staining/\nPuzzle solution", "align": "left", "width": 100}, {"id": "5266c351-7b99-5854-b598-2c1a516e3e7f", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/04/6F8836E1-9C95-4A74-9C4E-47EB78ABCA47.jpeg?resize=679%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}]'::jsonb,('2023-04-10T22:54:06'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
insert into public.posts (id,title,slug,excerpt,external_url,cover_image,category_id,additional_category_ids,status,content,created_at) values ('abfa05dd-b6dd-5402-a4c0-42f7b0fb3b8a','TYPES OF DNA DYES','types-of-dna-dyes','Types of DNA Dye The DNA dye may be primarily of THREE types The dye that binds in the minor groove of DNA The dye that is intercalated within the base pair Bis-intercalator Important features often the three types…','https://pathologymcq.com/types-of-dna-dyes/','https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/03/B520FD52-2233-4598-B53D-C4F4BCA60557.jpeg?resize=692%2C1024&ssl=1',(select id from public.categories where slug='histotechniques'),'{}'::uuid[],'published','[{"id": "85b9e3db-0ac9-5cb3-80df-64225371b5ce", "type": "paragraph", "text": "Types of DNA Dye\nThe DNA dye may be primarily of\nTHREE\ntypes\nThe dye that binds in the minor groove of DNA\nThe dye that is intercalated within the base pair\nBis-intercalator\nImportant features often the three types of DNA dyes are summarised in the image below.\nBasic Requirements of a Good DNA Dye\n• Dye should be specific to DNA.\n• Dye should bind stoichiometric to the DNA content.\n• Dye should show strong enhancement of fluorescence after binding with\nthe target.\nJOIN our\nTELEGRAM\nand\nWhatsApp\ngroup for daily MCQs\nSOME MCQS RELATED TO THE TOPIC\nDNA dyes\n100 MCQs on histotechniques\nhttps://pathologymcq.com/2023/03/01/frcpath-histopathology-mock-test/", "align": "left", "width": 100}, {"id": "34635652-c456-5e7f-a4b2-981ec8edab1e", "type": "image", "src": "https://i0.wp.com/pathologymcq.com/wp-content/uploads/2023/03/B520FD52-2233-4598-B53D-C4F4BCA60557.jpeg?resize=692%2C1024&ssl=1", "alt": "", "align": "left", "width": 100}]'::jsonb,('2023-03-07T13:30:28'::timestamp at time zone 'Asia/Kolkata')) on conflict do nothing;
